INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-9019936', 'course-bili-season-9019936', '100001', '0', 'BILI-PM-022', 'course-category-product', 'instructor-bili-3537117948938706', '广东自考产品设计', '4 讲完整课程 · 4 小时 34 分钟', '📘产品开发设计 专项精讲 ✅产品设计专业备考本课程的自考考生适用 ✅开发流程容易记混、产品方案分析不会作答、综合设计大题拿不到高分的零基础、在职备考同学 梳理产品开发流程、市场调研与用户需求分析、概念生成与方案筛选、造', '课程简介：📘产品开发设计 专项精讲 ✅产品设计专业备考本课程的自考考生适用 ✅开发流程容易记混、产品方案分析不会作答、综合设计大题拿不到高分的零基础、在职备考同学 梳理产品开发流程、市场调研与用户需求分析、概念生成与方案筛选、造型设计、原型开发、测试评估、产品商业化、设计约束条件等核心板块，拆解完整产品开发逻辑，区分不同开发模式的特点，整理名词解释、简答、综合设计题标准答题框架，结合真题梳理高频考点。开发阶段混淆分不清、不会分析产品案例、设计类大题不知道怎么组织答案都能针对性解决。课程结合实际产品案例拆解考点，精简背诵内容，搭建设计题答题逻辑。视频系列持续更新，欢迎评论区一起交流💬 课程结构：共 1 章 4 讲，累计时长 4 小时 34 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/c1b257dc5c2264d5be82d9445c40cacc6aec79a2.jpg', '["产品经理","需求分析","项目实战","广东自考产品设计"]', 16485, 4, 37, '4.2', 5, 'BV1CM8v6UEJy', '49.00', '78.40', 'CNY', 0, 0, 'standard', NULL, '上班族自考课程中心', 0, 'tenant', 'published', '2026-08-24T08:10:07.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
