INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1te1pyfetr', 'course-bili-bv1te1pyfetr', '100001', '0', 'BILI-PM-042', 'course-category-product', 'instructor-bili-243688560', '【IBM丨AI产品经理】AI产品战略与初始计划，了解AI、重塑AI产品，可领证书，认可度高，全套课程资料免费领取，Coursera官方会员2折优惠！', '38 讲完整课程 · 3 小时 12 分钟', '还有IBM官方认证技术证书哦~ 产品经理在企业中的职责是推动产品战略的制定和实施。他们与利益相关者有效合作，通过高影响力的产品解决方案改变企业', '还有IBM官方认证技术证书哦~ 产品经理在企业中的职责是推动产品战略的制定和实施。他们与利益相关者有效合作，通过高影响力的产品解决方案改变企业的业务方式。本课程将概述产品管理生命周期。您将详细了解产品构思和计划阶段。您将发现用于产品概念识别的工具和技术。您还将掌握使用 SWOT 分析和产品概念文档的技能。本课程还将帮助您做好组建团队和制定项目章程的准备。动手实验室将帮助您练习使用市场需求文件进行市场和解决方案分析。您还将调查产品商业案例并进行财务分析。在整个课程中，几位产品管理专家将分享他们在产品管理方面的见解和经验。实践测验和分级测验将测试您的知识。您将能够在最终项目中应用课程中学到的概念。本课程适合有志于申请产品管理职位并了解产品管理中使用的各种生命周期（包括敏捷）的人士。本课程不要求任何学位。课程结构：共 5 章 38 讲，累计时长 3 小时 12 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'intermediate', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/f31463c460e9f538a76505638f2ee918d4994e86.jpg', '["产品经理","需求分析","项目实战","IBM丨AI产品经理","AI产品战略与初始计划","了解AI"]', 11574, 38, 90, '4.3', 27, 'BV1TE1pYFETr', NULL, NULL, NULL, 1, 0, 'standard', NULL, '全球优质课程资源', 0, 'tenant', 'published', '2024-10-26T04:17:23.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
