INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv1ubxfeueub', 'course-bili-bv1ubxfeueub', '100001', '0', 'BILI-PM-074', 'course-category-product', 'instructor-bili-243688560', '【Product Management: An Introduction丨产品经理】IBM官方课程，Coursera课程证书，成为产品经理敲门砖！', '38 讲完整课程 · 3 小时 27 分钟', '在当今瞬息万变的全球市场中，公司需要技术精湛的产品经理来开发突破性产品或扩展现有产品。课程结束后，您将了解产品经理的职责以及成为产品经理所需的技能。对于希望开始产品管理职业生涯的人来说，本入门课程是一项有价值的投资。', '课程简介：在当今瞬息万变的全球市场中，公司需要技术精湛的产品经理来开发突破性产品或扩展现有产品。课程结束后，您将了解产品经理的职责以及成为产品经理所需的技能。对于希望开始产品管理职业生涯的人来说，本入门课程是一项有价值的投资。学习关键的产品管理概念，如产品生命周期、角色、价值创造和 SWOT 分析。了解产品管理的工作机会和行业标准《产品管理知识体系指南》（ProdBoK®）。实践实验室提供了在模拟现实环境中研究产品管理的机会。您将听到行业专家讨论他们的观点，从而了解他们的第一手经验。本课程是一系列课程中的第一门，完成后您将获得 IBM 产品管理专业证书。任何人都可以学习这门初级课程，无需任何产品管理技能或背景。还有Coursera官方认证技术证书哦~ 课程结构：共 5 章 38 讲，累计时长 3 小时 27 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/8832d3d64c4dac70dd586e08098767952b6be657.jpg', '["产品经理","需求分析","项目实战","Product","Management","An"]', 12442, 38, 1147, '4.3', 339, 'BV1uBxFeuEUb', NULL, NULL, NULL, 1, 0, 'standard', NULL, '全球优质课程资源', 0, 'tenant', 'published', '2024-09-27T10:06:47.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
