INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-bv19e41167dk', 'course-bili-bv19e41167dk', '100001', '0', 'BILI-PM-088', 'course-category-product', 'instructor-bili-435799943', '产品经理极客班-从入门到精通（珍藏版）', '93 讲完整课程 · 37 小时 40 分钟', '将会有得到更多产品材料分享。【产品训练总成】PM.产品经理极客班 【声明】自学教程，教程源于网络，请联系删除 【注意事项】请文明发送弹幕，禁止黄赌毒，视频中的三方链接不要轻信', '将会有得到更多产品材料分享。【产品训练总成】PM.产品经理极客班 【声明】自学教程，教程源于网络，请联系删除 【注意事项】请文明发送弹幕，禁止黄赌毒，视频中的三方链接不要轻信 【特别声明】有钱可以给UP爱心投喂,没钱硬币收藏点赞三连也是极好的，视频有用的话请务必点赞,让更多的人有机会学习 课程结构：共 12 章 93 讲，累计时长 37 小时 40 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'beginner', 'zh-CN', 'https://i0.hdslb.com/bfs/archive/6609115852aded43603cbf93954a89df45d4bfc1.jpg', '["产品经理","需求分析","项目实战","产品经理极客班","从入门到精通","珍藏版"]', 135603, 93, 3369, '4.3', 1095, 'BV19E41167Dk', NULL, NULL, NULL, 1, 0, 'standard', NULL, 'IT矿工', 0, 'tenant', 'published', '2019-10-21T07:34:11.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
