INSERT INTO course_catalog
    (id, uuid, tenant_id, organization_id, course_code, category_id, primary_instructor_id, title, subtitle, summary, description, learning_objectives_json, target_audience_json, prerequisites_json, difficulty_level, language_code, cover_resource_snapshot, tags_json, estimated_duration_seconds, lesson_count_snapshot, student_count_snapshot, rating_score_snapshot, rating_count_snapshot, external_source_id, price_amount, original_price_amount, currency, is_free, is_collection, course_kind, author_user_id, author_display_name, review_round, visibility, publish_status, published_at, status, created_at, created_by, updated_at, updated_by, version)
VALUES
    ('course-bili-season-1602779', 'course-bili-season-1602779', '100001', '0', 'BILI-PM-096', 'course-category-product', 'instructor-bili-28238054', '商业模式画布实战：如何描述和设计有效的商业模式', '24 讲完整课程 · 25 小时 51 分钟', '在这一讲中，我首先讲了一个案例：站在投资人的角度决策该如何从三个候选项目中选择一个项目来投资🔍 然后我又接着上节课的内容，举例并讲解完了商业模式画布剩下的四个模块（包括：核心资源、关键业务、重要合作、成本结构）📚 接', '课程简介：在这一讲中，我首先讲了一个案例：站在投资人的角度决策该如何从三个候选项目中选择一个项目来投资🔍 然后我又接着上节课的内容，举例并讲解完了商业模式画布剩下的四个模块（包括：核心资源、关键业务、重要合作、成本结构）📚 接着，我又强调了商业模式画布的九大模块是如何有机组合在一起的，以及我们该怎样利用商业模式画布设计自己的商业模式🚀 最后，我以Google和Metro公司为例介绍了如何用商业模式画布描述一家企业的商业模式💼 课程结构：共 1 章 24 讲，累计时长 25 小时 51 分钟，视频画面与课程封面同源。学习方式：按章节顺序观看即可，每讲均可在课程播放器中直接播放 B 站官方视频。', '["建立从用户洞察到产品方案的结构化产品思维","掌握需求调研、竞品分析与 PRD 撰写方法","能独立完成原型设计与需求评审","理解增长、商业化与跨团队协作的落地路径"]', '["零基础转行产品经理的职场人","需要补齐产品方法论的研发与运营","在校学生与应届生"]', '["对互联网产品有基本使用体验","无需技术背景，课程从零讲起"]', 'intermediate', 'zh-CN', 'https://archive.biliimg.com/bfs/archive/df645edbbf597ef54f5e4a8c86489e8830631c36.jpg', '["产品经理","需求分析","项目实战","商业模式画布实战"]', 93071, 24, 583, '4.4', 55, 'BV1B94y1r73i', NULL, NULL, NULL, 1, 0, 'standard', NULL, '陈鹏宇老师', 0, 'tenant', 'published', '2023-08-13T04:00:00.000Z', 'active', CURRENT_TIMESTAMP::text, 'catalog-seed', CURRENT_TIMESTAMP::text, 'catalog-seed', 0)
